package com.canberravision.prishashopper;
import android.Manifest;import android.app.Activity;import android.content.ContentValues;import android.content.Intent;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.Build;import android.os.Bundle;import android.provider.MediaStore;import android.util.Base64;import android.view.Window;import android.webkit.JavascriptInterface;import android.webkit.PermissionRequest;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.webkit.WebResourceRequest;import android.widget.Toast;import java.io.OutputStream;import java.text.SimpleDateFormat;import java.util.Date;import java.util.Locale;
public class MainActivity extends Activity{
 private static final String GAME_URL="https://sanketptt.com/sanket-game/";private static final int MIC_REQUEST=710;private WebView web;
 @Override protected void onCreate(Bundle state){super.onCreate(state);Window w=getWindow();w.setStatusBarColor(Color.rgb(18,52,90));w.setNavigationBarColor(Color.rgb(18,52,90));web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(false);s.setAllowContentAccess(true);web.addJavascriptInterface(new ShareBridge(),"AndroidBridge");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&"sanketptt.com".equals(u.getHost()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}});web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){boolean ok=r.getOrigin()!=null&&"https://sanketptt.com".equals(r.getOrigin().getScheme()+"://"+r.getOrigin().getHost())&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;if(ok)runOnUiThread(()->r.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE}));else runOnUiThread(r::deny);}});if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC_REQUEST);else loadGame(state);}
 private void loadGame(Bundle b){if(b!=null)web.restoreState(b);else web.loadUrl(GAME_URL);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==MIC_REQUEST){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)loadGame(null);else{Toast.makeText(this,"Microphone access is needed for voice shopping.",Toast.LENGTH_LONG).show();loadGame(null);}}}
 private Uri savePng(String data)throws Exception{byte[] bytes=Base64.decode(data,Base64.DEFAULT);String stamp=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date());ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"Prisha_Shopper_Report_"+stamp+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Prisha Shopper");v.put(MediaStore.Images.Media.IS_PENDING,1);Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IllegalStateException("Image save failed");try(OutputStream o=getContentResolver().openOutputStream(u)){o.write(bytes);}v.clear();v.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(u,v,null,null);return u;}
 public class ShareBridge{
  @JavascriptInterface public void saveReportImage(String b){try{savePng(b);runOnUiThread(()->Toast.makeText(MainActivity.this,"Report saved in Pictures / Prisha Shopper",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"Could not save report image",Toast.LENGTH_LONG).show());}}
  @JavascriptInterface public void shareReportImage(String b,String caption){try{Uri u=savePng(b);runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("image/png");i.putExtra(Intent.EXTRA_STREAM,u);i.putExtra(Intent.EXTRA_TEXT,caption);i.setClipData(android.content.ClipData.newUri(getContentResolver(),"Prisha Shopper report",u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Share Prisha's shopping report"));});}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"Could not share report image",Toast.LENGTH_LONG).show());}}
 }
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);web.saveState(b);}@Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}@Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}